import{_ as d,c as e,o,b2 as a}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"定时任务（Quartz）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/job-scheduler.md","filePath":"docs/backend/modules/job-scheduler.md"}'),r={name:"docs/backend/modules/job-scheduler.md"};function c(l,t,i,n,h,s){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="定时任务-quartz" tabindex="-1">定时任务（Quartz） <a class="header-anchor vp-link" href="#定时任务-quartz" aria-label="Permalink to &quot;定时任务（Quartz）&quot;">​</a></h1><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysJobController</code>、<code>SysJobLogController</code></td></tr><tr><td>路径</td><td><code>/monitor/job</code>、<code>/monitor/jobLog</code></td></tr><tr><td>前端</td><td><code>views/monitor/job/</code>、<code>job-log/</code></td></tr><tr><td>表</td><td><code>sys_job</code> 及 Quartz 表（Flyway V19+）</td></tr></tbody></table></div><h2 id="任务管理接口" tabindex="-1">任务管理接口 <a class="header-anchor vp-link" href="#任务管理接口" aria-label="Permalink to &quot;任务管理接口&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/monitor/job/list</code></td><td>任务列表</td></tr><tr><td>GET</td><td><code>/invokeTargets</code></td><td>可选执行目标（Bean 方法）</td></tr><tr><td>GET</td><td><code>/{jobId}</code></td><td>详情</td></tr><tr><td>POST</td><td><code>/edit</code></td><td>新增/修改</td></tr><tr><td>POST</td><td><code>/remove</code></td><td>删除</td></tr><tr><td>POST</td><td><code>/changeStatus</code></td><td>启停</td></tr><tr><td>POST</td><td><code>/run</code></td><td>立即执行一次</td></tr><tr><td>POST</td><td><code>/export</code></td><td>导出</td></tr></tbody></table></div><h2 id="任务日志" tabindex="-1">任务日志 <a class="header-anchor vp-link" href="#任务日志" aria-label="Permalink to &quot;任务日志&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/monitor/jobLog/list</code></td><td>执行记录</td></tr><tr><td>GET</td><td><code>/{jobLogId}</code></td><td>详情</td></tr><tr><td>POST</td><td><code>/remove</code>、<code>/clean</code></td><td>清理</td></tr><tr><td>POST</td><td><code>/export</code></td><td>导出</td></tr></tbody></table></div><h2 id="执行机制" tabindex="-1">执行机制 <a class="header-anchor vp-link" href="#执行机制" aria-label="Permalink to &quot;执行机制&quot;">​</a></h2><ul><li><code>AbstractQuartzJob</code> 封装执行与异常记录</li><li><code>ScheduleUtils</code> 维护 Cron 触发器</li><li><code>JobInvokeTargetRegistry</code> 注册可调用的 Spring Bean 方法</li><li>示例任务：<code>QcDemoTask</code></li></ul><h2 id="配置" tabindex="-1">配置 <a class="header-anchor vp-link" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><ul><li><code>qc.monitor.job.export-limit</code>：导出条数上限</li><li>多实例部署时需保证 Quartz 集群表锁正确（见 Flyway <code>V21</code>、<code>V22</code>）</li></ul><h2 id="前端" tabindex="-1">前端 <a class="header-anchor vp-link" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>任务编辑表单使用 <code>components/Crontab</code> 生成 Cron 表达式；列表页为 C7JsonTable 模式。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./monitor-audit.html" class="vp-link">监控审计</a></li></ul>',14)])])}const m=d(r,[["render",c]]);export{u as __pageData,m as default};
